import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

export const contentUrl = new URL('../content/n5-support/vocabulary-examples.json', import.meta.url);
export const migrationUrl = new URL('../migrations/183_n5_vocabulary_support.sql', import.meta.url);

export function buildMigration(plan) {
  return `-- Reviewed supporting examples for the existing N5 Bab 4–20 vocabulary decks.
-- Generated by scripts/build-n5-vocabulary-support.mjs; edit the JSON corpus first.
-- Owner rows, core words/readings/meanings, IDs, memberships and conversations are immutable.
CREATE TABLE IF NOT EXISTS n5_vocabulary_backup_183 (
  vocabulary_id UUID PRIMARY KEY,
  chapter INTEGER NOT NULL,
  lesson_id UUID NOT NULL,
  before_vocabulary JSONB NOT NULL,
  before_examples JSONB NOT NULL,
  before_deck_items JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

DO $migration$
DECLARE
  plan JSONB := $content$${JSON.stringify(plan)}$content$::jsonb;
  item JSONB;
  chapter JSONB;
  example JSONB;
  actual JSONB;
  expected JSONB;
  before_examples JSONB;
  selected_id UUID;
  retained_ids UUID[];
  v_owner_id UUID;
  sequence_number INTEGER;
  matches INTEGER;
  backup_count INTEGER;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('curriculum-boundary:graph'));
  PERFORM pg_advisory_xact_lock(hashtext('curriculum-boundary:' || (plan->>'courseId')));
  IF jsonb_array_length(plan->'items')<>724 OR jsonb_array_length(plan->'chapters')<>17
    OR (SELECT count(DISTINCT p->>'vocabularyId') FROM jsonb_array_elements(plan->'items') p)<>724 THEN
    RAISE EXCEPTION '183: invalid reviewed vocabulary corpus';
  END IF;
  SELECT count(*) INTO matches FROM courses c WHERE c.id=(plan->>'courseId')::uuid AND c.slug='n5';
  IF matches<>1 THEN RAISE EXCEPTION '183: N5 course identity changed'; END IF;
  PERFORM 1 FROM modules m WHERE m.course_id=(plan->>'courseId')::uuid ORDER BY m.id FOR UPDATE;
  FOR chapter IN SELECT value FROM jsonb_array_elements(plan->'chapters') LOOP
    IF NOT EXISTS(SELECT 1 FROM modules m WHERE m.id=(chapter->>'moduleId')::uuid
      AND m.course_id=(plan->>'courseId')::uuid AND m.slug=chapter->>'slug'
      AND m.sort_order=(chapter->>'chapter')::integer) THEN
      RAISE EXCEPTION '183: chapter identity changed: %', chapter->>'chapter';
    END IF;
    PERFORM 1 FROM lessons l WHERE l.module_id=(chapter->>'moduleId')::uuid ORDER BY l.id FOR UPDATE;
    SELECT coalesce(jsonb_agg(l.id::text ORDER BY l.id::text),'[]'::jsonb) INTO actual
      FROM lessons l WHERE l.module_id=(chapter->>'moduleId')::uuid AND l.type='deck';
    SELECT jsonb_agg(v ORDER BY v) INTO expected FROM jsonb_array_elements(chapter->'deckIds') v;
    IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION '183: chapter deck identity changed'; END IF;
    SELECT coalesce(jsonb_agg(d.vocabulary_id::text ORDER BY d.vocabulary_id::text),'[]'::jsonb) INTO actual
      FROM lesson_deck_items d WHERE d.lesson_id IN (SELECT value::text::uuid
        FROM jsonb_array_elements_text(chapter->'deckIds'));
    SELECT jsonb_agg(p->>'vocabularyId' ORDER BY p->>'vocabularyId') INTO expected
      FROM jsonb_array_elements(plan->'items') p WHERE p->'chapter'=chapter->'chapter';
    IF actual IS DISTINCT FROM expected THEN
      RAISE EXCEPTION '183: chapter deck membership changed: %', chapter->>'chapter';
    END IF;
  END LOOP;

  -- Owner rows can belong to the shared Bab 3 bank. Deck membership is the scope.
  -- Lock all target owners first; FK checks also prevent new unreviewed consumers.
  PERFORM 1 FROM module_vocabulary v WHERE v.id IN
    (SELECT (p->>'vocabularyId')::uuid FROM jsonb_array_elements(plan->'items') p) ORDER BY v.id FOR UPDATE;
  PERFORM 1 FROM lesson_deck_items d WHERE d.vocabulary_id IN
    (SELECT (p->>'vocabularyId')::uuid FROM jsonb_array_elements(plan->'items') p)
    ORDER BY d.vocabulary_id,d.lesson_id FOR UPDATE;
  PERFORM 1 FROM vocabulary_examples e WHERE e.vocabulary_id IN
    (SELECT (p->>'vocabularyId')::uuid FROM jsonb_array_elements(plan->'items') p) ORDER BY e.id FOR UPDATE;
  FOR item IN SELECT value FROM jsonb_array_elements(plan->'items') LOOP
    v_owner_id:=(item->>'vocabularyId')::uuid;
    IF NOT EXISTS(SELECT 1 FROM module_vocabulary v WHERE v.id=v_owner_id AND to_jsonb(v) @> (item->'expectedCore')) THEN
      RAISE EXCEPTION '183: core vocabulary changed: %', item->>'word';
    END IF;
    SELECT coalesce(jsonb_agg(d.lesson_id::text ORDER BY d.lesson_id::text),'[]'::jsonb) INTO actual
      FROM lesson_deck_items d WHERE d.vocabulary_id=v_owner_id;
    IF actual IS DISTINCT FROM item->'expectedDeckIds' THEN
      RAISE EXCEPTION '183: unexpected vocabulary consumer (including other courses): %', item->>'word';
    END IF;
    IF jsonb_array_length(item->'examples') NOT BETWEEN 2 AND 3 THEN
      RAISE EXCEPTION '183: expected two or three examples';
    END IF;
    FOR example IN SELECT value FROM jsonb_array_elements(item->'examples') LOOP
      IF coalesce(btrim(example->>'japanese'),'')='' OR coalesce(btrim(example->>'reading'),'')=''
        OR coalesce(btrim(example->>'highlight'),'')='' OR coalesce(btrim(example->>'indonesian'),'')=''
        OR position(example->>'highlight' IN example->>'japanese')=0 THEN
        RAISE EXCEPTION '183: incomplete reviewed example: %', item->>'word';
      END IF;
    END LOOP;
  END LOOP;

  SELECT count(*) INTO backup_count FROM n5_vocabulary_backup_183;
  IF backup_count=724 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(plan->'items') p
    WHERE NOT EXISTS(SELECT 1 FROM n5_vocabulary_backup_183 b WHERE b.vocabulary_id=(p->>'vocabularyId')::uuid
      AND b.lesson_id=(p->>'lessonId')::uuid AND b.chapter=(p->>'chapter')::integer)) THEN
    -- Manual reruns preserve any subsequent teacher edits to supporting examples.
    RETURN;
  ELSIF backup_count<>0 THEN
    RAISE EXCEPTION '183: partial or unexpected backup; refusing replacement';
  END IF;

  -- Compare all four public source fields as a multiset (including nulls/duplicates).
  FOR item IN SELECT value FROM jsonb_array_elements(plan->'items') LOOP
    SELECT coalesce(jsonb_agg(x ORDER BY x),'[]'::jsonb) INTO actual FROM (
      SELECT jsonb_build_object('japanese',e.japanese,'reading',e.reading,'highlight',e.highlight,'indonesian',e.indonesian) x
        FROM vocabulary_examples e WHERE e.vocabulary_id=(item->>'vocabularyId')::uuid) source;
    SELECT coalesce(jsonb_agg(value ORDER BY value),'[]'::jsonb) INTO expected FROM jsonb_array_elements(item->'sourceExamples');
    IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION '183: source examples changed: %', item->>'word'; END IF;
  END LOOP;

  -- Snapshot ALL rows before the first replacement, not only examples being retained.
  INSERT INTO n5_vocabulary_backup_183(vocabulary_id,chapter,lesson_id,before_vocabulary,before_examples,before_deck_items)
    SELECT v.id,(p->>'chapter')::integer,(p->>'lessonId')::uuid,to_jsonb(v),
      coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.sort_order,e.id) FROM vocabulary_examples e WHERE e.vocabulary_id=v.id),'[]'::jsonb),
      coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY d.lesson_id) FROM lesson_deck_items d WHERE d.vocabulary_id=v.id),'[]'::jsonb)
    FROM jsonb_array_elements(plan->'items') p JOIN module_vocabulary v ON v.id=(p->>'vocabularyId')::uuid;
  GET DIAGNOSTICS matches=ROW_COUNT;
  IF matches<>724 THEN RAISE EXCEPTION '183: incomplete snapshot'; END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(plan->'items') LOOP
    v_owner_id:=(item->>'vocabularyId')::uuid;
    SELECT b.before_examples INTO before_examples FROM n5_vocabulary_backup_183 b WHERE b.vocabulary_id=v_owner_id;
    retained_ids:=ARRAY[]::uuid[];
    sequence_number:=0;
    FOR example IN SELECT value FROM jsonb_array_elements(item->'examples') LOOP
      -- Keep the original ID when retaining an example; reuse remaining old slots
      -- for corrected examples. Allocate IDs only where no prior slot exists.
      SELECT (old->>'id')::uuid INTO selected_id FROM jsonb_array_elements(before_examples) old
        WHERE NOT ((old->>'id')::uuid=ANY(retained_ids))
        ORDER BY (jsonb_build_object('japanese',old->'japanese','reading',old->'reading',
          'highlight',old->'highlight','indonesian',old->'indonesian')=example) DESC,
          (old->>'sort_order')::integer,old->>'id' LIMIT 1;
      IF selected_id IS NULL THEN selected_id:=gen_random_uuid(); END IF;
      INSERT INTO vocabulary_examples(id,vocabulary_id,japanese,reading,highlight,indonesian,sort_order)
        VALUES(selected_id,v_owner_id,example->>'japanese',example->>'reading',example->>'highlight',example->>'indonesian',sequence_number)
        ON CONFLICT(id) DO UPDATE SET japanese=EXCLUDED.japanese,reading=EXCLUDED.reading,
          highlight=EXCLUDED.highlight,indonesian=EXCLUDED.indonesian,sort_order=EXCLUDED.sort_order;
      retained_ids:=array_append(retained_ids,selected_id);
      sequence_number:=sequence_number+1;
    END LOOP;
    DELETE FROM vocabulary_examples e WHERE e.vocabulary_id=v_owner_id AND NOT(e.id=ANY(retained_ids));
  END LOOP;
  SELECT count(*) INTO matches FROM vocabulary_examples e WHERE e.vocabulary_id IN
    (SELECT (p->>'vocabularyId')::uuid FROM jsonb_array_elements(plan->'items') p);
  IF matches<>(SELECT sum(jsonb_array_length(p->'examples')) FROM jsonb_array_elements(plan->'items') p) THEN
    RAISE EXCEPTION '183: replacement example count mismatch';
  END IF;
END
$migration$;
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const sql = buildMigration(JSON.parse(fs.readFileSync(contentUrl, 'utf8')));
  if (process.argv.includes('--check')) {
    if (fs.readFileSync(migrationUrl, 'utf8').replaceAll('\r\n', '\n') !== sql) throw new Error('Regenerate migration 183 from its vocabulary corpus');
  } else fs.writeFileSync(migrationUrl, sql);
}
